-- Polyizon PropOS comprehensive rental operations layer
CREATE TABLE IF NOT EXISTS tenant_contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, tenant_id uuid NOT NULL REFERENCES rental_tenants(id) ON DELETE CASCADE, contact_type text NOT NULL, name text NOT NULL, phone text, email text, relationship text, is_primary boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tenant_kyc (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, tenant_id uuid NOT NULL REFERENCES rental_tenants(id) ON DELETE CASCADE, document_type text, document_number text, employer text, status text NOT NULL DEFAULT 'pending', verified_at timestamptz, consent_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lease_parties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, lease_id uuid NOT NULL REFERENCES leases(id) ON DELETE CASCADE, tenant_id uuid REFERENCES rental_tenants(id), party_type text NOT NULL, name text NOT NULL, phone text, email text, liability_percent numeric(7,4), guarantee_amount numeric(14,2), start_date date, end_date date, metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS rent_schedules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, lease_id uuid NOT NULL REFERENCES leases(id) ON DELETE CASCADE, charge_code text NOT NULL DEFAULT 'rent', amount numeric(14,2) NOT NULL, frequency text NOT NULL DEFAULT 'monthly', due_day int, starts_on date NOT NULL, ends_on date, escalation_type text, escalation_value numeric(10,4), next_escalation_on date, grace_days int NOT NULL DEFAULT 0, proration_method text NOT NULL DEFAULT 'daily', active boolean NOT NULL DEFAULT true, metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS charge_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, property_id uuid REFERENCES properties(id) ON DELETE CASCADE, name text NOT NULL, charge_type text NOT NULL, calculation_type text NOT NULL DEFAULT 'fixed', amount numeric(14,2), rate numeric(10,4), grace_days int DEFAULT 0, recurring boolean NOT NULL DEFAULT true, active boolean NOT NULL DEFAULT true, metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS tenant_wallet_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, tenant_id uuid NOT NULL REFERENCES rental_tenants(id) ON DELETE CASCADE, entry_type text NOT NULL, amount numeric(14,2) NOT NULL, reference text, source_type text, source_id uuid, posted_at timestamptz NOT NULL DEFAULT now(), metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS payment_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, tenant_id uuid NOT NULL REFERENCES rental_tenants(id), lease_id uuid REFERENCES leases(id), original_balance numeric(14,2) NOT NULL, installment_amount numeric(14,2) NOT NULL, frequency text NOT NULL DEFAULT 'monthly', starts_on date NOT NULL, status text NOT NULL DEFAULT 'active', next_due_on date, created_by uuid REFERENCES users(id), metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lease_amendments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, lease_id uuid NOT NULL REFERENCES leases(id) ON DELETE CASCADE, version int NOT NULL, amendment_type text NOT NULL, effective_on date NOT NULL, summary text NOT NULL, terms jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'draft', signed_at timestamptz, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(lease_id,version));
CREATE TABLE IF NOT EXISTS vacancy_turnovers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, unit_id uuid NOT NULL REFERENCES units(id) ON DELETE CASCADE, vacated_on date, target_ready_on date, ready_on date, target_rent numeric(14,2), status text NOT NULL DEFAULT 'make_ready', cleaning_status text, repair_status text, inspection_status text, keys_status text, marketing_status text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS rental_leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, property_id uuid REFERENCES properties(id), unit_id uuid REFERENCES units(id), name text NOT NULL, phone text, email text, source text, stage text NOT NULL DEFAULT 'inquiry', score int, desired_move_in date, budget numeric(14,2), lost_reason text, assigned_to uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS property_viewings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, lead_id uuid REFERENCES rental_leads(id) ON DELETE CASCADE, property_id uuid REFERENCES properties(id), unit_id uuid REFERENCES units(id), scheduled_at timestamptz NOT NULL, agent_id uuid REFERENCES users(id), status text NOT NULL DEFAULT 'scheduled', feedback text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS property_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, property_id uuid NOT NULL REFERENCES properties(id) ON DELETE CASCADE, unit_id uuid REFERENCES units(id), asset_type text NOT NULL, name text NOT NULL, serial_number text, warranty_expires_on date, service_interval_days int, next_service_on date, status text NOT NULL DEFAULT 'active', metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS access_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, property_id uuid NOT NULL REFERENCES properties(id), unit_id uuid REFERENCES units(id), tenant_id uuid REFERENCES rental_tenants(id), item_type text NOT NULL, tag text, issued_at timestamptz, returned_at timestamptz, status text NOT NULL DEFAULT 'available', metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS parking_allocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, property_id uuid NOT NULL REFERENCES properties(id), unit_id uuid REFERENCES units(id), tenant_id uuid REFERENCES rental_tenants(id), bay_code text NOT NULL, vehicle_plate text, monthly_fee numeric(14,2) DEFAULT 0, starts_on date, ends_on date, status text NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS visitor_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, property_id uuid NOT NULL REFERENCES properties(id), unit_id uuid REFERENCES units(id), visitor_name text NOT NULL, phone text, vehicle_plate text, checked_in_at timestamptz NOT NULL DEFAULT now(), checked_out_at timestamptz, approved_by text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS inventory_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, property_id uuid REFERENCES properties(id), unit_id uuid REFERENCES units(id), name text NOT NULL, category text, quantity numeric(12,3) NOT NULL DEFAULT 1, condition text, replacement_cost numeric(14,2), serial_number text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS complaints (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, property_id uuid REFERENCES properties(id), unit_id uuid REFERENCES units(id), tenant_id uuid REFERENCES rental_tenants(id), category text NOT NULL, priority text NOT NULL DEFAULT 'normal', subject text NOT NULL, description text, status text NOT NULL DEFAULT 'open', assigned_to uuid REFERENCES users(id), resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS management_mandates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, property_id uuid NOT NULL REFERENCES properties(id), owner_id uuid REFERENCES property_owners(id), starts_on date NOT NULL, ends_on date, management_fee_type text NOT NULL DEFAULT 'percent_collected', management_fee_value numeric(10,4) NOT NULL DEFAULT 0, leasing_fee numeric(14,2) DEFAULT 0, renewal_fee numeric(14,2) DEFAULT 0, maintenance_markup numeric(10,4) DEFAULT 0, reserve_minimum numeric(14,2) DEFAULT 0, expense_approval_threshold numeric(14,2), status text NOT NULL DEFAULT 'active', metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS owner_reserve_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, owner_id uuid NOT NULL REFERENCES property_owners(id), property_id uuid REFERENCES properties(id), entry_type text NOT NULL, amount numeric(14,2) NOT NULL, reference text, posted_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS procurement_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, property_id uuid REFERENCES properties(id), requested_by uuid REFERENCES users(id), title text NOT NULL, estimated_amount numeric(14,2), status text NOT NULL DEFAULT 'requested', needed_by date, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS legal_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, tenant_id uuid REFERENCES rental_tenants(id), lease_id uuid REFERENCES leases(id), property_id uuid REFERENCES properties(id), case_type text NOT NULL, stage text NOT NULL, advocate text, exposure_amount numeric(14,2), next_action_on date, status text NOT NULL DEFAULT 'open', metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS compliance_obligations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, property_id uuid REFERENCES properties(id), obligation_type text NOT NULL, authority text, certificate_number text, due_on date, expires_on date, status text NOT NULL DEFAULT 'current', document_id uuid REFERENCES documents(id), metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS property_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, property_id uuid REFERENCES properties(id), unit_id uuid REFERENCES units(id), tenant_id uuid REFERENCES rental_tenants(id), assigned_to uuid REFERENCES users(id), title text NOT NULL, priority text NOT NULL DEFAULT 'normal', due_at timestamptz, status text NOT NULL DEFAULT 'open', source_type text, source_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS accounting_periods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, period_start date NOT NULL, period_end date NOT NULL, status text NOT NULL DEFAULT 'open', locked_at timestamptz, locked_by uuid REFERENCES users(id), reopened_at timestamptz, reopened_by uuid REFERENCES users(id), UNIQUE(organization_id,period_start,period_end));
CREATE TABLE IF NOT EXISTS rent_roll_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, snapshot_date date NOT NULL, property_id uuid REFERENCES properties(id), total_units int NOT NULL DEFAULT 0, occupied_units int NOT NULL DEFAULT 0, scheduled_rent numeric(14,2) NOT NULL DEFAULT 0, collected_rent numeric(14,2) NOT NULL DEFAULT 0, arrears numeric(14,2) NOT NULL DEFAULT 0, payload jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(organization_id,snapshot_date,property_id));
CREATE INDEX IF NOT EXISTS idx_rent_schedules_org_lease ON rent_schedules(organization_id,lease_id);
CREATE INDEX IF NOT EXISTS idx_rental_leads_org_stage ON rental_leads(organization_id,stage);
CREATE INDEX IF NOT EXISTS idx_turnovers_org_status ON vacancy_turnovers(organization_id,status);
CREATE INDEX IF NOT EXISTS idx_complaints_org_status ON complaints(organization_id,status);
CREATE INDEX IF NOT EXISTS idx_legal_cases_org_status ON legal_cases(organization_id,status);
CREATE INDEX IF NOT EXISTS idx_compliance_org_due ON compliance_obligations(organization_id,due_on);
CREATE INDEX IF NOT EXISTS idx_tasks_org_due ON property_tasks(organization_id,status,due_at);
